#!/usr/bin/env node
import {
	startLocalBridge,
	browserTools,
	serveMcp,
	decodeTicket,
} from "./server.mjs";
const [command, ...args] = process.argv.slice(2);
if (command === "mcp") {
	const encoded = args[args.indexOf("--bind") + 1];
	if (!args.includes("--bind"))
		throw Error(
			"Choose Connect this page on the website and copy its MCP configuration.",
		);
	const bridge = await startLocalBridge(encoded);
	const server = await serveMcp({
		name: "hopper-browser-agent",
		version: "0.1.0",
		tools: browserTools(bridge),
	});
	const close = async () => {
		await bridge.close();
		await server.close();
		process.exit(0);
	};
	process.once("SIGINT", close);
	process.once("SIGTERM", close);
	process.stdin.once("end", close);
} else if (command === "doctor") {
	const encoded = args[args.indexOf("--bind") + 1];
	if (args.includes("--bind")) decodeTicket(encoded);
	console.log(
		JSON.stringify(
			{
				node: process.versions.node,
				supported: Number(process.versions.node.split(".")[0]) >= 22,
				protocol: "MCP stdio",
				binding: args.includes("--bind")
					? "valid ticket; use page_status after launching MCP"
					: "Choose Connect this page to generate a binding",
			},
			null,
			2,
		),
	);
} else
	console.log(
		"hopper-browser-agent mcp --bind <page-ticket>\nhopper-browser-agent doctor [--bind <page-ticket>]\nUse the configuration generated by the exact browser page.",
	);
